import{_ as a,o as s,c as r,e as i}from"./chunks/framework.Cq4gzU1W.js";const m=JSON.parse('{"title":"Scratch","description":"Scratch un lenguaje de programación divertido","frontmatter":{"title":"Scratch ","description":"Scratch un lenguaje de programación divertido","weight":10,"draft":false,"icon":"fas fa-bug"},"headers":[],"relativePath":"scratch/estructuras-secuenciales/index.md","filePath":"04_Scratch/03_Secuenciales/index.md"}'),o={name:"scratch/estructuras-secuenciales/index.md"};function t(c,e,n,d,l,u){return s(),r("div",null,[...e[0]||(e[0]=[i('<div class="daws-objetivos"><div class="daws-objetivos__header"><i class="fa-solid fa-list-check" aria-hidden="true"></i><span>Objetivos</span></div><div class="daws-objetivos__content"><div class="daws-objetivos__title"> Objetivos </div><div class="daws-objetivos__body"><p>Acceder a scratch para programar Ver el entorno de ejecución</p></div></div></div><h1 id="estructuras-secuenciales" tabindex="-1">Estructuras secuenciales <a class="header-anchor" href="#estructuras-secuenciales" aria-label="Permalink to &quot;Estructuras secuenciales&quot;">​</a></h1><p>Cuando programamos, lo más habitual es que las instrucciones se ejecuten <strong>una detrás de otra, siguiendo un orden determinado</strong>.</p><p>Esta forma de organizar las instrucciones se denomina <strong>estructura secuencial</strong> y es la más sencilla de la programación.</p><p>El ordenador ejecuta la primera instrucción, después la segunda, luego la tercera... hasta completar todas las acciones.</p><p>Por ejemplo, imaginemos que queremos que un personaje de Scratch:</p><ol><li>🚶 Avance 50 pasos.</li><li>⏰ Espere 2 segundos.</li><li>🔄 Gire 90 grados.</li><li>💬 Diga «¡He terminado!».</li></ol><p>El orden es importante: si cambiamos el orden de las instrucciones, el resultado del programa puede ser diferente.</p><p>En Scratch encontramos instrucciones secuenciales principalmente en las siguientes categorías:</p><ul><li>🔵 <strong>Movimiento:</strong> desplazar, girar o cambiar la posición de un personaje.</li><li>🟣 <strong>Apariencia:</strong> mostrar mensajes, cambiar disfraces o modificar el tamaño.</li><li>🩷 <strong>Sonido:</strong> reproducir sonidos o modificar el volumen.</li></ul><p>Estas instrucciones se representan mediante <strong>bloques que podemos encajar unos debajo de otros</strong>, indicando así el orden en el que deben ejecutarse.</p><div class="tip custom-block"><p class="custom-block-title">💡 Idea fundamental</p><p>Una estructura secuencial consiste en <strong>ejecutar instrucciones una detrás de otra, en el orden en el que aparecen</strong>.</p><p>Es la base de cualquier programa y, combinándola con las estructuras selectivas y repetitivas, podremos construir programas mucho más complejos.</p><p>En PHP también escribiremos instrucciones secuenciales, pero en lugar de utilizar bloques gráficos, las escribiremos mediante código.</p></div><h2 id="estudo-en-scratch" tabindex="-1">Estudo en scratch <a class="header-anchor" href="#estudo-en-scratch" aria-label="Permalink to &quot;Estudo en scratch&quot;">​</a></h2><div class="iframe-container"><iframe src="https://es.wikieducator.org/index.php?curid=6650" width="100%" height="6152">WikiEducator </iframe></div>',14)])])}const g=a(o,[["render",t]]);export{m as __pageData,g as default};
